<?php
namespace App\Models\Task; use App\Models\Concerns\HasPublicUuid; use App\Models\Customer\Tag; use App\Models\User; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany; use Illuminate\Database\Eloquent\Relations\MorphToMany; use Illuminate\Database\Eloquent\SoftDeletes;
class Task extends Model { use HasPublicUuid,SoftDeletes; protected $fillable=['title','description','status','priority','assigned_to','created_by','due_at','completed_at','related_type','related_id','parent_task_id']; protected function casts():array{return ['due_at'=>'datetime','completed_at'=>'datetime'];} public function assignee():BelongsTo{return $this->belongsTo(User::class,'assigned_to');} public function creator():BelongsTo{return $this->belongsTo(User::class,'created_by');} public function parent():BelongsTo{return $this->belongsTo(self::class,'parent_task_id');} public function subtasks():HasMany{return $this->hasMany(self::class,'parent_task_id');} public function tags():MorphToMany{return $this->morphToMany(Tag::class,'taggable')->withPivot(['assigned_by','created_at']);} }
